tableInfo.sqlForTool:
{1}
SELECT trim(DISEASE_CD) as DISEASE_CD,DISEASE_NAME,DISEASE_NAME_ABBR_1,TRIM(IN_HOSPITAL_CD) AS IN_HOSPITAL_CD,DEL_FLG,'0' AS IS_DIE,UP_DATE FROM MST_DISEASE A WHERE NOT EXISTS (SELECT * FROM MST_DISEASE B WHERE A.DISEASE_CD=B.DISEASE_CD AND A.UP_DATE<B.UP_DATE)
{sqlForSync}
{2}
ORDER BY DISEASE_CD

{1}
select trim(a.DISEASE_CD) as DISEASE_CD,a.DISEASE_NAME,a.DEL_FLG,'1' as IS_DIE,UP_DATE from mst_die a where not exists(select * from mst_die b where a.disease_cd=b.disease_cd and a.up_date<b.up_date)
{sqlForSync}
{2}
order by a.disease_cd

{1}
SELECT INJURY_CD,INJURY_NAME,TRIM(IN_HOSPITAL_CD) AS IN_HOSPITAL_CD,DEL_FLG,UP_DATE FROM MST_INJURY A WHERE NOT EXISTS (SELECT * FROM MST_INJURY B WHERE A.INJURY_CD=B.INJURY_CD AND A.UP_DATE<B.UP_DATE)
{sqlForSync}
{2}
ORDER BY INJURY_CD

{1}
SELECT TRANSPORT_CD,TRANSPORT_NAME,TRIM(IN_HOSPITAL_CD) AS IN_HOSPITAL_CD,DEL_FLG,UP_DATE FROM MST_TRANSPORT A WHERE NOT EXISTS (SELECT * FROM MST_TRANSPORT B WHERE A.TRANSPORT_CD=B.TRANSPORT_CD AND A.UP_DATE<B.UP_DATE)
{sqlForSync}
{2}
ORDER BY TRANSPORT_CD

{1}
select a.COURSE_CD,a.COURSE_NAME,TRIM(a.IN_HOSPITAL_CD) AS IN_HOSPITAL_CD,a.DEL_FLG,b.DISP_FLG,b.DISP_ORDER,a.UP_DATE from MST_COURSE a inner join MST_COURSE_SUB_NEW b on(a.COURSE_CD=b.COURSE_CD AND a.UP_DATE=b.UP_DATE) where b.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{2}
ORDER BY b.DISP_ORDER NULLS LAST,a.COURSE_CD

{1}
SELECT a.WARD_CD,a.WARD_NAME,TRIM(a.IN_HOSPITAL_CD) AS IN_HOSPITAL_CD,decode(a.DEL_FLG,'1','0',b.DISP_FLG) AS DISP_FLG,b.DISP_ORDER,a.UP_DATE  FROM MST_WARD a inner join MST_WARD_SUB_NEW b on(a.WARD_CD=b.WARD_CD and a.UP_DATE=b.UP_DATE) where b.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{2}
ORDER BY b.DISP_ORDER NULLS LAST,a.WARD_CD

{1}
select a.ADDITION_CD,a.INDICATION,decode(a.DEL_FLG,'1','0',b.DISP_FLG) AS DISP_FLG,b.DISP_ORDER,null as OCCUPATIONS,a.UP_DATE from MST_IND_ADDITION a
inner join MST_IND_ADDITION_SUB_NEW b on(a.ADDITION_CD=b.ADDITION_CD and a.UP_DATE=b.UP_DATE)
where b.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{2}
order by b.DISP_ORDER,a.UP_DATE,a.ADDITION_CD

{1}
SELECT CLASS_CD,CLASS_NAME,DEL_FLG,EDIT_FLG,UP_DATE FROM MST_CLASS_NAME A WHERE NOT EXISTS (SELECT * FROM MST_CLASS_NAME B WHERE A.CLASS_KIND=B.CLASS_KIND AND A.CLASS_CD=B.CLASS_CD AND A.UP_DATE<B.UP_DATE) AND A.CLASS_KIND='3'
{sqlForSync}
{2}
ORDER BY CLASS_KIND,CLASS_CD

{1}
SELECT CLASS_CD,CLASS_NAME,DEL_FLG,EDIT_FLG,UP_DATE FROM MST_CLASS_NAME A WHERE NOT EXISTS (SELECT * FROM MST_CLASS_NAME B WHERE A.CLASS_KIND=B.CLASS_KIND AND A.CLASS_CD=B.CLASS_CD AND A.UP_DATE<B.UP_DATE) AND CLASS_KIND='2'
{sqlForSync}
{2}
UNION ALL
SELECT 'SN'  AS CLASS_CD,CONCAT(CLASS_NAME, '(SN)') AS CLASS_NAME,DEL_FLG,EDIT_FLG,UP_DATE FROM MST_CLASS_NAME A WHERE NOT EXISTS (SELECT * FROM MST_CLASS_NAME B WHERE A.CLASS_KIND=B.CLASS_KIND AND A.CLASS_CD=B.CLASS_CD AND A.UP_DATE<B.UP_DATE) AND CLASS_KIND='2' AND CLASS_CD = '202'
{sqlForSync}
{2}
ORDER BY CLASS_CD

{1}
SELECT a.TABOO_GROUP_CD,a.UP_DATE,a.TABOO_GROUP_NAME,TRIM(a.IN_HOSPITAL_CD1) AS IN_HOSPITAL_CD1,TRIM(a.IN_HOSPITAL_CD2) AS IN_HOSPITAL_CD2,decode(a.DEL_FLG,'1','0',b.DISP_FLG) AS DISP_FLG,b.DISP_ORDER  FROM MST_TABOO_GROUP a inner join MST_TABOO_GROUP_SUB_NEW b on (a.TABOO_GROUP_CD=b.TABOO_GROUP_CD and a.UP_DATE=b.UP_DATE) where b.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{2}
ORDER BY b.DISP_ORDER,a.TABOO_GROUP_CD

child.sqlForTool:
with sys_treat_sn as(
select treat_item_cd,use_flg from SYS_TREAT_COND_SETTING
where cond_ctl_no ='029'
),
target_ctl_no as (
select to_char(LEVEL) as ctl_no from DUAL where LEVEL>=9 connect by LEVEL <= 12
)
select a.treat_item_cd,b.ctl_no,a.use_flg from sys_treat_sn a natural join target_ctl_no b
{sqlForSync}
order by a.treat_item_cd,to_number(b.ctl_no)

tableInfo.sqlForTool:
{1}
SELECT a.TIMING_CD, a.UP_DATE, a.TIMING_NAME, a.DIALYSIS_PROG_CD, decode(a.DEL_FLG,'1','0',b.DISP_FLG) AS DISP_FLG, b.ALERT_TIME, b.ALERT_FLG,b.DISP_ORDER,a.UP_DATE FROM MST_TIMING a inner join MST_TIMING_SUB_NEW b on a.TIMING_CD = b.TIMING_CD and a.UP_DATE = b.UP_DATE
where b.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{2}
ORDER BY b.DISP_ORDER,a.UP_DATE,a.TIMING_CD

{1}
SELECT a.KUR_CD,a.KUR_NAME,a.KUR_START_TIME,a.KUR_END_TIME,a.STANDARD_START_TIME,a.DEL_FLG,a.UP_DATE  FROM MST_KUR a WHERE NOT EXISTS(SELECT * FROM MST_KUR b WHERE a.KUR_CD=b.KUR_CD AND a.UP_DATE<b.UP_DATE)
{sqlForSync}
{2}
ORDER BY a.KUR_CD

{1}
SELECT BED_GROUP_NO,BED_GROUP_NAME,DEL_FLG,1 AS GROUP_CLASS,REG_DATE FROM MST_BED_GROUP a
WHERE NOT EXISTS(SELECT * FROM MST_BED_GROUP b WHERE a.BED_GROUP_NO=b.BED_GROUP_NO AND a.REG_DATE<b.REG_DATE)
AND a.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{3}
ORDER BY BED_GROUP_NO

{1}
select a.room_cd,a.room_name,2 as group_class,TRIM(a.in_hospital_cd1) AS in_hospital_cd1,TRIM(a.in_hospital_cd2) AS in_hospital_cd2,TRIM(a.in_hospital_cd3) AS in_hospital_cd3,a.del_flg,a.up_date from mst_room a
where not exists(select * from mst_room b where a.room_cd=b.room_cd and a.up_date<b.up_date)
AND a.SERIES_CD = '{SERIES_CD}'
{sqlForSync}
{3}
order by room_cd

{1}
select trim(a.STAFF_CD) DISP_USER_ID,trim(a.STAFF_CD) as STAFF_CD ,a.PASSWORD,b.DISP_ORDER,b.DISP_FLG as  DISP_FLG_1,a.UP_DATE from v_mst_staff a left outer join (select STAFF_CD,DISP_ORDER,DISP_FLG from SYS_STAFF_DISP where SERIES_CD='{SERIES_CD}') b on (a.STAFF_CD = b.STAFF_CD)
{sqlForSync}
where 1=1
{2}
ORDER BY b.DISP_ORDER  nulls last,b.STAFF_CD

{1}
select * from(
select 1 as PKEY,'' as DUMMY_COLUMN,to_char(sysdate,'yyyy-mm-dd') as UP_DATE from dual) a
{2}
{3}

WITH PAT_BASIC_INFO_NORMAL AS
(SELECT w1.* FROM PAT_BASIC_INFO w1 INNER JOIN PAT_INDEX_INFO w2 ON(w1.PATID=w2.PATID AND w1.REG_DATE=w2.PAT_REG_DATE)
INNER JOIN (SELECT DISTINCT PATID, SERIES_CD
FROM (
SELECT PATID, FROM_SERIES_CD AS SERIES_CD
FROM SYS_PAT_MOVE_PLAN 
UNION ALL
SELECT PATID, TO_SERIES_CD
FROM SYS_PAT_MOVE_PLAN  {STATUS}
UNION ALL
SELECT PATID, SERIES_CD
FROM SYS_PAT_SERIES_FACILITY where MAIN_FLG='1'
)) s on s.PATID=w1.PATID and s.SERIES_CD='{SERIES_CD}'
)
{1}
SELECT PATID,REG_DATE,DEL_FLG FROM PAT_BASIC_INFO_NORMAL a
{sqlForSync}
{2}
{3}
ORDER BY PATID

{1}
select trim(MEDICINE_GROUP_CD) as MEDICINE_GROUP_CD, UP_DATE, MEDICINE_GROUP_NAME, MEDICINE_GROUP_UNIT, WEEK_FLG, GRAPH_UPPER, GRAPH_LOWER, DEL_FLG
from MST_MEDICINE_GROUP a where not exists(select * from MST_MEDICINE_GROUP b where a.MEDICINE_GROUP_CD=b.MEDICINE_GROUP_CD and a.UP_DATE<b.UP_DATE)
{sqlForSync}
{2}
{3}
order by MEDICINE_GROUP_CD

{1}
select
TEMPLATE_NO,
TEMPLATE_NAME,
'1' as disp_period_class,
decode(a.DEL_FLG,'1','0','1') AS DISP_FLG,UP_DATE
from SYS_MUL_TEMP a
where 1=1
{sqlForSync}
{2}
