order by TEMPLATE_NAME

child.sqlForTool:
WITH MST_SET_MEDI_NAME_LIST AS( select a.SET_MEDICINE_CD, a.SET_MEDICINE_NAME from MST_SET_MEDI_NAME a inner join MST_SET_MEDI_NAME_SUB_NEW b on(a.SET_MEDICINE_CD = b.SET_MEDICINE_CD and a.UP_DATE = b.UP_DATE) where b.SERIES_CD = '{SERIES_CD}' ), EXAM_ITEM_UPPERORLOWER as ( SELECT TO_CHAR(COALESCE( GRAPH_UPPER, 0)) AS UPPER, TO_CHAR(COALESCE(GRAPH_LOWER, 0)) AS LOWER, EXAM_ITEM_CD FROM MST_EXAM_ITEM_SUB_NEW where SERIES_CD = '{SERIES_CD}' ), DW_UPPERORLOWER as( select TO_CHAR(ROUND(MAX(TO_NUMBER(VALUE))*1.1)) AS DW_UPPER ,TO_CHAR(ROUND(MIN(TO_NUMBER(VALUE))*0.9)) AS DW_LOWER from RST_DIALYSIS_COND where CTL_NO = '004' ),grouped_results AS ( SELECT a.TEMPLATE_NO, a.GRAPH_NO , CASE WHEN COUNT(CASE WHEN GRAPH_KIND NOT IN (2, 3) THEN 1 END) = 0 THEN 2 WHEN MIN(GRAPH_KIND) = MAX(GRAPH_KIND) and MAX(GRAPH_KIND)!=4 THEN MAX(GRAPH_KIND) ELSE -1 END AS RESULT_GRAPH_KIND FROM (select TEMPLATE_NO,GRAPH_NO,ITEM_NO,DISP_FLG,CODE,MED_KBN,ORDER_CLASS,DIAL_COND_KBN,COLOR,REGRESSION_FLG,REGRESS_COLOR,UP_DATE,DEL_FLG, case when GRAPH_KIND =4 and DIAL_COND_KBN in ('3','4','8','9','10','11','7') then 0 else GRAPH_KIND end as GRAPH_KIND from SYS_MUL_GRAPH_DETAIL) a INNER JOIN SYS_MUL_GRAPH g on g.TEMPLATE_NO=a.TEMPLATE_NO and g.GRAPH_NO=a.GRAPH_NO where g.GRAPH_SIZE!=0 and (GRAPH_KIND NOT IN ('1', '2', '3','5') OR (GRAPH_KIND IN ('1', '2', '3') AND CODE IS NOT NULL)) GROUP BY a.TEMPLATE_NO, a.GRAPH_NO
), template_stats AS ( SELECT TEMPLATE_NO, COUNT(*) AS total_count, SUM(CASE WHEN RESULT_GRAPH_KIND IN (1,2,0) THEN 1 ELSE 0 END) AS valid_count FROM grouped_results GROUP BY TEMPLATE_NO ), GET_SUBCATEGORYNAME as( SELECT g.TEMPLATE_NO, g.GRAPH_NO, CASE WHEN t.total_count = t.valid_count AND g.GRAPH_NO = 4 THEN -1 ELSE g.RESULT_GRAPH_KIND END AS RESULT_GRAPH_KIND FROM grouped_results g JOIN template_stats t ON g.TEMPLATE_NO = t.TEMPLATE_NO ORDER BY g.TEMPLATE_NO, g.GRAPH_NO ), dat_list as ( select a.*,i.COMPONENT,i.CATEGORYNO,i.CATEGORYNAME, i.SUBCATEGORYNAME || CASE WHEN GRAPH_KIND=0 OR ITEM_NO=0 THEN '①' ELSE CASE WHEN ITEM_NO=1 THEN '②' ELSE '③' END END AS SUBCATEGORYNAME from ( select DENSE_RANK() over (partition by a.TEMPLATE_NO, s.RESULT_GRAPH_KIND ORDER BY a.TEMPLATE_NO, a.GRAPH_NO) as no, a.TEMPLATE_NO, case when GRAPH_KIND in (2,3) then 2 else GRAPH_KIND end as GRAPH_KIND, case GRAPH_KIND when 0 then 1 when 1 then 2 when 2 then 4 when 3 then 4 when 4 then case when DIAL_COND_KBN in ('3','4','8','9','10','11','7') then 1 else 3 end end itemDivision, case when (GRAPH_KIND='3' or GRAPH_KIND='2') and MED_KBN = '1' then CODE when GRAPH_KIND='0' then case ITEM_NO when 0 then 'weight_before' when 1 then 'weight_after' when 2 then 'rst_dw' when 3 then 'ctr' end when GRAPH_KIND='4' then case DIAL_COND_KBN when 0 then 'dializer' when 1 then 'treatment_time' when 2 then 'blood_flow' when 3 then 'ktv_measurements' when 4 then 'urr' when 5 then 'method_of_treatment' when 6 then 'dialysate_flow_rate' when 7 then 'fluid_volume' when 8 then 'water_removal_rst' when 9 then 're_loop_rate_main' when 10 then 'sttc_vns_prssr' when 11 then 'iap_rt' end else CODE end as itemNo, case when GRAPH_KIND = 4 then case DIAL_COND_KBN when 0 then 'ダイアライザ' when 1 then '治療時間' when 2 then '血流量' when 3 then 'Kt/V測定値' when 4 then 'URR' when 5 then '治療方法' when 6 then '透析液流量' when 7 then '補液量' when 8 then '除水量' when 9 then '再循環率' when 10 then '静的静脈圧' when 11 then 'IAP rate' end when GRAPH_KIND=1 then ( select EXAM_ITEM_NAME from (SELECT EXAM_ITEM_NAME,EXAM_ITEM_CD from MST_EXAM_ITEM order by REG_DATE desc) where EXAM_ITEM_CD=CODE and rownum=1) when GRAPH_KIND='3' or GRAPH_KIND='2' then case MED_KBN when 1 then ( select MEDICINE_GROUP_NAME from (SELECT MEDICINE_GROUP_NAME,MEDICINE_GROUP_CD from MST_MEDICINE_GROUP order by UP_DATE desc) where MEDICINE_GROUP_CD=CODE and rownum=1) when 0 then ( select MEDICINE_NAME from (SELECT MEDICINE_NAME,MEDICINE_CD from MST_MEDICINE order by UP_DATE desc) where MEDICINE_CD=CODE and rownum=1) when 2 then SET_MEDICINE_NAME end when GRAPH_KIND = 0 then case ITEM_NO when 0 then '透析前体重' when 1 then '透析後体重' when 2 then 'DW' when 3 then 'CTR' end end itemName, case GRAPH_KIND when 3 then '処方' when 2 then '投薬' end graph, case when GRAPH_KIND='3' or GRAPH_KIND='2' then 'day' end as ITEMDATE, nvl(to_char(COLOR),-16777216) as color, case when GRAPH_KIND！='3' and GRAPH_KIND！='2' then case SYMBOL when 0 then 'circle' when 1 then 'circle-b' when 2 then 'double-circle' when 3 then 'triangle' when 4 then 'triangle-b' when 5 then 'triangle-down' when 6 then 'riangle-down-b' when 7 then 'square' when 8 then 'square-b' when 9 then 'diamond' when 10 then 'diamond-b' end end as SUBCATEGORYITEM,MED_KBN, case when a.GRAPH_KIND =4 then '実績' else '指示' end treatmentStatus, '結果' as inspectionStatus, s.RESULT_GRAPH_KIND ,case when a.GRAPH_KIND='3' or a.GRAPH_KIND='2' then case MED_KBN when 1 then ( select TO_CHAR( COALESCE(GRAPH_UPPER, 0)) from (SELECT GRAPH_UPPER,MEDICINE_GROUP_CD from MST_MEDICINE_GROUP order by UP_DATE desc) where MEDICINE_GROUP_CD=CODE and rownum=1) else '0' end when a.GRAPH_KIND='1' then UPPER when a.GRAPH_KIND='0' then DW_UPPER
when a.GRAPH_KIND = 4 then case DIAL_COND_KBN when 0 then '' when 1 then (select TO_CHAR(VALUE*60) from SYS_SYSTEM_DEFINE WHERE ID='215' and SERIES_CD='{SERIES_CD}') when 2 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='217' and SERIES_CD='{SERIES_CD}') when 3 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='583' and SERIES_CD='{SERIES_CD}') when 4 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='588' and SERIES_CD='{SERIES_CD}') when 5 then '' when 6 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='221' and SERIES_CD='{SERIES_CD}') when 7 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='223' and SERIES_CD='{SERIES_CD}') when 8 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='225' and SERIES_CD='{SERIES_CD}') when 9 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='227' and SERIES_CD='{SERIES_CD}') when 10 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='233' and SERIES_CD='{SERIES_CD}') when 11 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='235' and SERIES_CD='{SERIES_CD}') end end graphMax ,case when a.GRAPH_KIND='3' or a.GRAPH_KIND='2' then case MED_KBN when 1 then ( select TO_CHAR(COALESCE(GRAPH_LOWER, 0)) from (SELECT GRAPH_LOWER,MEDICINE_GROUP_CD from MST_MEDICINE_GROUP order by UP_DATE desc) where MEDICINE_GROUP_CD=CODE and rownum=1) else '0' end when a.GRAPH_KIND='1' then LOWER when a.GRAPH_KIND='0' then DW_LOWER when a.GRAPH_KIND = 4 then case DIAL_COND_KBN when 0 then '' when 1 then (select TO_CHAR(VALUE*60) from SYS_SYSTEM_DEFINE WHERE ID='216' and SERIES_CD='{SERIES_CD}') when 2 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='218' and SERIES_CD='{SERIES_CD}') when 3 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='584' and SERIES_CD='{SERIES_CD}') when 4 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='589' and SERIES_CD='{SERIES_CD}') when 5 then '' when 6 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='222' and SERIES_CD='{SERIES_CD}') when 7 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='224' and SERIES_CD='{SERIES_CD}') when 8 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='226' and SERIES_CD='{SERIES_CD}') when 9 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='228' and SERIES_CD='{SERIES_CD}') when 10 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='234' and SERIES_CD='{SERIES_CD}') when 11 then (select VALUE from SYS_SYSTEM_DEFINE WHERE ID='236' and SERIES_CD='{SERIES_CD}') end end graphMin,ITEM_NO,a.GRAPH_NO,case ORDER_CLASS when -1 then 3 when 0 then 1 when 1 then 2 when 2 then 0 else null end as ITEMEXAMCLASS ,case when GRAPH_KIND in (2,3) then '実績' else '指示' end drugStatus from (select t.* , row_number() over (partition by TEMPLATE_NO ORDER BY TEMPLATE_NO) as seq from SYS_MUL_GRAPH_DETAIL t) a INNER JOIN SYS_MUL_GRAPH g on g.TEMPLATE_NO=a.TEMPLATE_NO and g.GRAPH_NO=a.GRAPH_NO INNER JOIN GET_SUBCATEGORYNAME s on s.TEMPLATE_NO=a.TEMPLATE_NO and s.GRAPH_NO=a.GRAPH_NO left join mst_set_medi_name_list s on s.SET_MEDICINE_CD=a.CODE and a.MED_KBN=2 and a.GRAPH_KIND in(2,3) LEFT JOIN EXAM_ITEM_UPPERORLOWER b on b.EXAM_ITEM_CD=a.CODE and a.GRAPH_KIND='1' CROSS JOIN DW_UPPERORLOWER where DISP_FLG = '1' AND (GRAPH_KIND NOT IN ('1', '2', '3','5') OR (GRAPH_KIND IN ('1', '2', '3') AND CODE IS NOT NULL)) and g.GRAPH_SIZE!=0 and a.ITEM_NO <=2 ) a INNER JOIN SYNC_DISP_ITEM_INFO i on a.no=i.no and a.RESULT_GRAPH_KIND=i.GRAPHKIND) select * from ( select * from dat_list UNION ALL select a.*,i.COMPONENT,i.CATEGORYNO,i.CATEGORYNAME,'体重グラフ②' AS from ( select DISTINCT d.no, a.TEMPLATE_NO, a.GRAPH_KIND, 1 AS itemDivision, 'ctr' as itemNo, 'CTR' AS itemName, NULL AS graph, NULL as ITEMDATE, nvl(to_char(a.COLOR),-16777216) as color, case when a.GRAPH_KIND！='3' and a.GRAPH_KIND！='2' then case a.SYMBOL when 0 then 'circle' when 1 then 'circle-b' when 2 then 'double-circle' when 3 then 'triangle' when 4 then 'triangle-b' when 5 then 'triangle-down' when 6 then 'riangle-down-b' when 7 then 'square' when 8 then 'square-b' when 9 then 'diamond' when 10 then 'diamond-b' end end as SUBCATEGORYITEM, a.MED_KBN ,'指示' as treatmentStatus ,'結果' as inspectionStatus ,0 as RESULT_GRAPH_KIND ,(select VALUE from SYS_SYSTEM_DEFINE WHERE ID='211' and SERIES_CD='{SERIES_CD}') as graphMax ,(select VALUE from SYS_SYSTEM_DEFINE WHERE ID='212' and SERIES_CD='{SERIES_CD}') as graphMin ,a.ITEM_NO,a.GRAPH_NO ,null as ITEMEXAMCLASS ,'指示' as drugStatus from (select t.* , row_number() over (partition by TEMPLATE_NO ORDER BY TEMPLATE_NO) as seq from SYS_MUL_GRAPH_DETAIL t) a INNER JOIN SYS_MUL_GRAPH g on g.TEMPLATE_NO=a.TEMPLATE_NO and g.GRAPH_NO=a.GRAPH_NO INNER JOIN dat_list d on d.TEMPLATE_NO=a.TEMPLATE_NO and d.GRAPH_NO=a.GRAPH_NO where a.DISP_FLG = '1' and a.GRAPH_KIND='0' and a.ITEM_NO=3 and g.GRAPH_SIZE!=0) a INNER JOIN SYNC_DISP_ITEM_INFO i on a.no=i.no and i.GRAPHKIND=0 UNION ALL select 1, TEMPLATE_NO, null, null, TO_CHAR(TEMPLATE_NO) as itemNo, null,null,null,null,null,null,null,null,null,null,null,null,5,null,null,'medicationSupport','1028',null,null from (select a.TEMPLATE_NO, case when b.TEMPLATE_NO is null and MED_GROUP_CODE1 is null and MED_GROUP_CODE2 is null and MED_GROUP_CODE3 is null then '0' else decode(a.DEL_FLG,'1','0','1') end DEL_FLG from SYS_MUL_TEMP a left join ( select TEMPLATE_NO from SYS_MED_SUPPORT_TEST WHERE EXAM_ITEM_NO is not null GROUP BY TEMPLATE_NO) b on a.TEMPLATE_NO = b.TEMPLATE_NO) where DEL_FLG=1 ) a order by a.TEMPLATE_NO, a.GRAPH_NO, a.ITEM_NO

tableInfo.sqlForTool:
{1}
SELECT '3日・7日・14日' as TEMPLATE_NAME,MAX(a.UP_DATE) AS UP_DATE,'0' as DISP_PERIOD_CLASS ,'00' as  TEMPLATE_NO
FROM SYS_ACTCHART_DEFINE a 
WHERE a.ctl_no NOT IN ('001','006')  AND a.SERIES_CD = '{SERIES_CD}'
{2}

{1}
{treatmentSetCd}
select '1' as PKEY,'初期セット' as treatment_set_name, {initValue}, '1' as is_disp, '0' as is_del, '' as DUMMY_COLUMN,a.UP_DATE
from sys_actchart_define a ,
(
select ctl_no as ctl_no2 , max(up_date) as up_date2 from sys_actchart_define where SERIES_CD = '{SERIES_CD}' group by ctl_no order by 1
) sad2
{treatmentCd}
where  a.SERIES_CD = '{SERIES_CD}' and a.CTL_NO = sad2.ctl_no2 and a.UP_DATE = sad2.up_date2
{3}
order by a.CTL_NO

WITH SYS_PAT_SERIES_FACILITY_LIST as ( SELECT DISTINCT PATID, SERIES_CD FROM ( SELECT PATID, FROM_SERIES_CD AS SERIES_CD FROM SYS_PAT_MOVE_PLAN UNION ALL SELECT PATID, TO_SERIES_CD FROM SYS_PAT_MOVE_PLAN {STATUS} UNION ALL SELECT PATID, SERIES_CD FROM SYS_PAT_SERIES_FACILITY where MAIN_FLG='1' ) ), PAT_BASIC_INFO_NORMAL AS (SELECT w1.*, regexp_replace(replace(ltrim(rtrim(name,' '),' '),' ',' '),'\s{2,}',' ') as trim_name, regexp_replace(replace(ltrim(rtrim(name_kana,' '),' '),' ',' '),'\s{2,}',' ') as trim_name_kana, nvl(lead (w1.REG_DATE, 1, NULL ) over ( PARTITION BY w1.PATID ORDER BY w1.PATID , w1.REG_DATE ASC ), SYSDATE ) AS prev_reg_date FROM PAT_BASIC_INFO w1 INNER JOIN PAT_INDEX_INFO w2 ON(w2.PAT_STATUS='0' AND w1.PATID=w2.PATID ) INNER JOIN SYS_PAT_SERIES_FACILITY_LIST s on s.PATID=w1.PATID and s.SERIES_CD='{SERIES_CD}' ) ,PAT_BASIC_INFO_NOW AS ( SELECT w1.PATID FROM PAT_BASIC_INFO w1 INNER JOIN PAT_INDEX_INFO w2 ON(w2.PAT_STATUS='0' AND w1.PATID=w2.PATID AND w1.REG_DATE=w2.PAT_REG_DATE ) INNER JOIN SYS_PAT_SERIES_FACILITY_LIST s on s.PATID=w1.PATID and s.SERIES_CD='{SERIES_CD}' ),PATID_UP_DATE_MAX AS ( SELECT b.PATID,max(b.UP_DATE) as REG_DATE FROM ( SELECT PATID, REG_DATE as UP_DATE FROM PAT_BASIC_INFO UNION ALL SELECT PATID,UP_DATE AS UP_DATE FROM PAT_INSURANCE UNION ALL SELECT PATID,UP_DATE FROM PAT_CONTACT UNION ALL SELECT PATID,UP_DATE FROM PAT_RECEIPT_MEMO WHERE '1' = ( SELECT VALUE FROM SYS_SYSTEM_DEFINE WHERE ID = '134' and SERIES_CD='{SERIES_CD}' ) ) b INNER JOIN SYS_PAT_SERIES_FACILITY_LIST s on s.PATID=b.PATID and s.SERIES_CD='{SERIES_CD}' GROUP BY b.PATID ) ,DIE_INFO AS( SELECT DISEASE_CD, DISEASE_NAME, UP_DATE, nvl(lead (UP_DATE, 1, NULL) over (PARTITION BY DISEASE_CD ORDER BY DISEASE_CD ,UP_DATE ASC), SYSDATE) AS enddate FROM MST_DIE ORDER BY DISEASE_CD,UP_DATE ),INJURY_INFO AS( SELECT INJURY_CD, INJURY_NAME, UP_DATE, nvl( lead (UP_DATE, 1, NULL) over (PARTITION BY INJURY_CD ORDER BY INJURY_CD ,UP_DATE ASC), SYSDATE) AS enddate FROM MST_INJURY ORDER BY INJURY_CD,UP_DATE ),TRANSPORT_INFO AS( SELECT TRANSPORT_CD, TRANSPORT_NAME, UP_DATE, nvl( lead ( UP_DATE, 1, NULL ) over ( PARTITION BY TRANSPORT_CD ORDER BY TRANSPORT_CD ,UP_DATE ASC), SYSDATE) AS enddate FROM MST_TRANSPORT ORDER BY TRANSPORT_CD,UP_DATE ),DISEASE_INFO AS( SELECT DISEASE_CD, DISEASE_NAME, UP_DATE, nvl( lead ( UP_DATE, 1, NULL ) over ( PARTITION BY DISEASE_CD ORDER BY DISEASE_CD ,UP_DATE ASC), SYSDATE) AS enddate FROM MST_DISEASE ORDER BY DISEASE_CD,UP_DATE ),PATID_UP_DATE AS ( SELECT b.PATID, b.UP_DATE as REG_DATE FROM ( SELECT PATID, REG_DATE as UP_DATE FROM PAT_BASIC_INFO UNION ALL SELECT PATID,UP_DATE AS UP_DATE FROM PAT_INSURANCE UNION ALL SELECT PATID,UP_DATE FROM PAT_CONTACT UNION ALL SELECT PATID,UP_DATE FROM PAT_RECEIPT_MEMO WHERE '1' = ( SELECT VALUE FROM SYS_SYSTEM_DEFINE WHERE ID = '134' and SERIES_CD='{SERIES_CD}') UNION ALL SELECT b.PATID , a.UP_DATE FROM MST_DIAL_DIFF_COMENT a JOIN PAT_BASIC_INFO_NOW b ON 1 = 1 INNER JOIN PATID_UP_DATE_MAX p on p.PATID=b.PATID and a.UP_DATE>p.REG_DATE {3} ) b GROUP BY b.PATID, b.UP_DATE ) {1} select a.*,'[]' as vendor_contact_info,'0' as REMOTE_MONITOR_SERVICE from (
SELECT a.PATID, CASE ISCHECKED WHEN '2' THEN ltrim(DISP_PATID,'0') WHEN '3' THEN substr(DISP_PATID, LINENUMBER) ELSE DISP_PATID END AS DISP_PATID, case when instr(trim_name,' ')=0 then trim_name when instr(trim_name,' ')>0 then substr(trim_name,0,instr(trim_name,' ')-1) end as sei, case when instr(trim_name,' ')>0 then substr(trim_name,instr(trim_name,' ')+1) else ' ' end as mei, case when instr(trim_name_kana,' ')=0 then trim_name_kana when instr(trim_name_kana,' ')>0 then substr(trim_name_kana,0,instr(trim_name_kana,' ')-1) end as sei_kana, case when instr(trim_name_kana,' ')>0 then substr(trim_name_kana,instr(trim_name_kana,' ')+1) else ' ' end as mei_kana, NAME,NAME_KANA,BIRTHDAY,SEX_CD,BLOOD_TYPE_ABO,BLOOD_TYPE_RH, CASE WHEN a.DIE_FLG = '1' THEN '2' ELSE a.INOUT_FLG END AS INOUT_FLG, DIE_FLG,DIE_CD,DIE_DATE,a.INJURY_CD,a.TRANSPORT_CD,trim(BASE_DISEASE_CD) as BASE_DISEASE_CD,c.REG_DATE,'1' AS FACILITY_NAME,c.DISEASE_NAME,i.INJURY_NAME,t.TRANSPORT_NAME,d.DISEASE_NAME AS BASE_DISEASE_NAME FROM PATID_UP_DATE c INNER JOIN PAT_BASIC_INFO_NORMAL a ON c.PATID = a.PATID AND c.REG_DATE = a.REG_DATE INNER JOIN SYNC_CONDSET s on s.SERIES_CD='{SERIES_CD}' left join DIE_INFO c on c.DISEASE_CD=a.DIE_CD and a.REG_DATE>c.UP_DATE and a.REG_DATE<c.enddate left join INJURY_INFO i on i.INJURY_CD=a.INJURY_CD and a.REG_DATE>i.UP_DATE and a.REG_DATE<i.enddate left join TRANSPORT_INFO t on t.TRANSPORT_CD=a.TRANSPORT_CD and a.REG_DATE>t.UP_DATE and a.REG_DATE<t.enddate left join DISEASE_INFO d on d.DISEASE_CD=a.BASE_DISEASE_CD and a.REG_DATE>d.UP_DATE and a.REG_DATE<d.enddate UNION ALL SELECT a.PATID, CASE ISCHECKED WHEN '2' THEN ltrim(DISP_PATID,'0') WHEN '3' THEN substr(DISP_PATID, LINENUMBER) ELSE DISP_PATID END AS DISP_PATID, case when instr(trim_name,' ')=0 then trim_name when instr(trim_name,' ')>0 then substr(trim_name,0,instr(trim_name,' ')-1) end as sei, case when instr(trim_name,' ')>0 then substr(trim_name,instr(trim_name,' ')+1) else ' ' end as mei, case when instr(trim_name_kana,' ')=0 then trim_name_kana when instr(trim_name_kana,' ')>0 then substr(trim_name_kana,0,instr(trim_name_kana,' ')-1) end as sei_kana, case when instr(trim_name_kana,' ')>0 then substr(trim_name_kana,instr(trim_name_kana,' ')+1) else ' ' end as mei_kana, NAME,NAME_KANA,BIRTHDAY,SEX_CD,BLOOD_TYPE_ABO,BLOOD_TYPE_RH, CASE WHEN a.DIE_FLG = '1' THEN '2' ELSE a.INOUT_FLG END AS INOUT_FLG, DIE_FLG,DIE_CD,DIE_DATE,a.INJURY_CD,a.TRANSPORT_CD,trim(BASE_DISEASE_CD) as BASE_DISEASE_CD,c.REG_DATE,'1' AS FACILITY_NAME,c.DISEASE_NAME,i.INJURY_NAME,t.TRANSPORT_NAME,d.DISEASE_NAME AS BASE_DISEASE_NAME FROM PATID_UP_DATE c INNER JOIN PAT_BASIC_INFO_NORMAL a ON c.PATID = a.PATID AND ( c.REG_DATE < a.prev_reg_date AND c.REG_DATE > a.REG_DATE ) INNER JOIN SYNC_CONDSET s on s.SERIES_CD='{SERIES_CD}' left join DIE_INFO c on c.DISEASE_CD=a.DIE_CD and a.REG_DATE>c.UP_DATE and a.REG_DATE<c.enddate left join INJURY_INFO i on i.INJURY_CD=a.INJURY_CD and a.REG_DATE>i.UP_DATE and a.REG_DATE<i.enddate left join TRANSPORT_INFO t on t.TRANSPORT_CD=a.TRANSPORT_CD and a.REG_DATE>t.UP_DATE and a.REG_DATE<t.enddate left join DISEASE_INFO d on d.DISEASE_CD=a.BASE_DISEASE_CD and a.REG_DATE>d.UP_DATE and a.REG_DATE<d.enddate ) a where a.PATID is not null {sqlForSync} {2}
ORDER BY a.PATID,a.REG_DATE
